SELECT

FROM ai_conversation
WHERE login_identity_id = #{loginIdentityId,jdbcType=BIGINT}
  AND is_active = TRUE
  AND last_message_id IS NOT NULL

    AND (last_message_id, id) < (
        #{beforeLastMessageId,jdbcType=BIGINT},
        #{beforeConversationId,jdbcType=BINARY}
    )

ORDER BY last_message_id DESC, id DESC
LIMIT #{limit,jdbcType=INTEGER}

mapper.update:
UPDATE ai_conversation
SET title = CASE
        WHEN last_message_id IS NULL
            THEN #{initialTitle,jdbcType=VARCHAR}
        ELSE title
    END,
    last_message_id = #{messageId,jdbcType=BIGINT}
WHERE id = #{conversationId,jdbcType=BINARY}
  AND (
      last_message_id IS NULL
      OR last_message_id < #{messageId,jdbcType=BIGINT}
  )

UPDATE ai_conversation
SET last_compacted_message_id = #{lastCompactedMessageId,jdbcType=BIGINT},
    compacted_context = CAST(#{compactedContextJson,jdbcType=VARCHAR} AS JSONB)
WHERE id = #{conversationId,jdbcType=BINARY}
  AND (
    (
      #{expectedLastCompactedMessageId,jdbcType=BIGINT} IS NULL
      AND last_compacted_message_id IS NULL
    )
    OR last_compacted_message_id =
       #{expectedLastCompactedMessageId,jdbcType=BIGINT}
  )
